  if (/\.(apk|obb)$/.test(n)) return "app-package";
  if (/\.(dex|odex|vdex|oat|art)$/.test(n)) return "android-runtime";
  if (/kgsl|mali|pvr|nvmap|dmabuf|ion|memfd|gpu/.test(n)) return "graphics";
