function safeValidateReport(value) {
  const result = reportSchema.safeParse(value);
  if (result.success) return { ok: true, report: result.data };
  return {
    ok: false,
    errors: result.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`)
  };
}

