    const body = rows.map(
      (row) => `<tr><td><strong>${esc4(row.subsystem)}</strong></td><td>${esc4(row.headline)}</td><td class="sub">${esc4(row.detail)}</td><td class="remark-cell">${statusPill(row.status, STATUS_LABEL[row.status])}</td></tr>`
    ).join("");
    const unmeasured = rows.filter((r) => r.status === "unmeasured").length;
