    const bursts = io && io.bursts.length > 0 ? `<h3>Heaviest reads</h3>
             <table class="data"><thead><tr><th class="num">At</th><th class="num">Read rate</th>
             <th class="num">From flash</th><th class="num">Frame rate then</th>
             <th class="num">Stutter</th><th>During</th></tr></thead>
             <tbody>${io.bursts.map(
      (b) => `<tr><td class="num">${esc4(formatClock(b.elapsedMs))}</td><td class="num">${(b.readBytesPerSecond / MB).toFixed(1)} MB/s</td><td class="num">${b.storageReadBytesPerSecond !== null ? `${(b.storageReadBytesPerSecond / MB).toFixed(1)} MB/s` : "\u2014"}</td><td class="num">${b.fps !== null ? `${b.fps} fps` : "\u2014"}</td><td class="num">${b.janks ?? "\u2014"}</td><td>${esc4(b.nearestMarker ?? "\u2014")}</td></tr>`
    ).join("")}</tbody></table>` : "";
