  regressed: { cls: "bad", mark: "\u2715", text: "worse" },
  unchanged: { cls: "flat", mark: "", text: "same" },
  inconclusive: { cls: "flat", mark: "", text: "within noise" },
  unknown: { cls: "na", mark: "", text: "not comparable" }
